<!doctype html><html><body style="font-family:Arial,sans-serif;color:#23312f;line-height:1.6"><div style="max-width:600px;margin:0 auto;padding:40px 24px"><p style="letter-spacing:.16em;color:#c26e46;font-size:12px;font-weight:bold">KUMBURUS</p><h1 style="font-family:Georgia,serif;font-size:36px;margin-bottom:8px">Your stay is confirmed.</h1><p>Hi {{ $booking->user->name }}, we’re looking forward to welcoming you.</p><div style="background:#f4eee7;padding:24px;margin:28px 0"><p style="margin:0;color:#c26e46;font-weight:bold">{{ $booking->confirmation_code }}</p><h2 style="font-family:Georgia,serif;margin-bottom:4px">{{ $booking->room->hotel->name }}</h2><p style="margin-top:0">{{ $booking->room->name }}</p><p><strong>Check in:</strong> {{ $booking->check_in->format('M d, Y') }}<br><strong>Check out:</strong> {{ $booking->check_out->format('M d, Y') }}<br><strong>Guests:</strong> {{ $booking->guests }}<br><strong>Total:</strong> ${{ number_format((float) $booking->total_amount, 2) }}</p></div><p>Keep this email for your records. See you soon.</p></div></body></html>
